// Discovers the services generated by the Power Apps CLI at build time:
//   pa app add data-source --connector dataverse --table pa_benchmarkrun
//   pa app add flow --flow-id <id>
// Using import.meta.glob means the app compiles even before anything is generated,
// and we don't depend on the exact class/file names the generator picks.
import type { IOperationResult } from '@microsoft/power-apps/data';

export type FlowRunner = (input?: Record<string, unknown>) => Promise<IOperationResult<unknown>>;

export interface GetAllOptions {
  select?: string[];
  filter?: string;
  orderBy?: string[];
  top?: number;
}
export interface TableService {
  getAll: (options?: GetAllOptions) => Promise<IOperationResult<Record<string, unknown>[]>>;
}

export interface DiscoveredService {
  exportName: string;
  file: string;
  kind: 'flow' | 'table' | 'other';
  key: string; // normalized name, e.g. "pocrespondearlyservice"
  impl: unknown;
}

const modules = import.meta.glob(['../generated/services/*.ts', '../services/*.ts']);

export const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

let cache: Promise<DiscoveredService[]> | undefined;

export function discoverServices(): Promise<DiscoveredService[]> {
  cache ??= (async () => {
    const found: DiscoveredService[] = [];
    for (const [file, load] of Object.entries(modules)) {
      try {
        const mod = (await load()) as Record<string, unknown>;
        for (const [exportName, value] of Object.entries(mod)) {
          if (typeof value !== 'function') continue;
          const v = value as unknown as Record<string, unknown>;
          const kind = typeof v.Run === 'function' ? 'flow' : typeof v.getAll === 'function' ? 'table' : 'other';
          found.push({ exportName, file, kind, key: normalize(exportName), impl: value });
        }
      } catch (e) {
        console.warn('Could not load generated service', file, e);
      }
    }
    return found;
  })();
  return cache;
}

export async function findFlow(namePart: string): Promise<FlowRunner | undefined> {
  const n = normalize(namePart);
  const flows = (await discoverServices()).filter((s) => s.kind === 'flow');
  // Exact name first ("UC1-SLOW" → UC1_SLOWService), so UC1 never resolves to UC10.
  const svc = flows.find((s) => s.key === n || s.key === `${n}service`) ?? flows.find((s) => s.key.includes(n));
  if (!svc) return undefined;
  const impl = svc.impl as { Run: FlowRunner };
  return (input) => impl.Run(input);
}

export async function hasFlow(namePart: string): Promise<boolean> {
  return (await findFlow(namePart)) !== undefined;
}

export async function findTable(namePart: string): Promise<TableService | undefined> {
  const n = normalize(namePart);
  const svc = (await discoverServices()).find((s) => s.kind === 'table' && s.key.includes(n));
  return svc?.impl as TableService | undefined;
}
